class ProfilePage extends StatelessWidget{const ProfilePage({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(appBar:AppBar(title:const Text('Mon profil')),body:StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').doc(uid).snapshots(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!.data()??{};return ListView(padding:const EdgeInsets.all(16),children:[const CircleAvatar(radius:45,child:Icon(Icons.person,size:50)),const SizedBox(height:16),Center(child:Text('${d['name']??'Utilisateur'}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w700))),const SizedBox(height:20),_row('Rôle','${d['role']??d['type']??'—'}'),_row('Téléphone','${d['phone']??'—'}'),_row('E-mail','${d['email']??'—'}'),_row('Localité','${d['village']??'—'}'),const SizedBox(height:16),FilledButton.icon(onPressed:()=>Navigator.pushNamed(context,AppRoutes.trainings),icon:const Icon(Icons.school_outlined),label:const Text('Mes formations')),OutlinedButton.icon(onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout),label:const Text('Se déconnecter'))]);}),bottomNavigationBar:const BaoBottomNav(selectedIndex:5));}Widget _row(String a,String b)=>Card(child:ListTile(title:Text(a),subtitle:Text(b)));}
